'use strict';
/**
 * dsh-math-assistant — Obsidian side-panel plugin for the DeepSeek Harness
 * math-memory agent.
 *
 * Generated by scripts/build-obsidian.mjs; edit obsidian/main.template.js
 * and the shared dsh/ files, then rebuild.
 */
const { Plugin, ItemView, Notice, PluginSettingTab, Setting, Modal } = require('obsidian');
const { shell } = require('electron');
const { spawn, spawnSync } = require('child_process');
const { existsSync, mkdirSync, writeFileSync, readFileSync, readdirSync, statSync, renameSync, symlinkSync, appendFileSync } = require('fs');
const { join, dirname, resolve } = require('path');
const { homedir } = require('os');
const { randomBytes } = require('crypto');
const http = require('http');
const { createServer } = http;

// ── file-based debug log (read directly by the maintainer) ──
let debugVaultPath = '';
function writeDebugLog(line) {
  try {
    if (debugVaultPath === '') return;
    const path = join(debugVaultPath, '.obsidian', 'plugins', 'dsh-math-assistant', 'debug.log');
    appendFileSync(path, '[' + new Date().toISOString() + '] ' + line + '\n', 'utf8');
  } catch {
    // instrumentation must never break the plugin
  }
}


const VIEW_TYPE = 'dsh-math-assistant-view';
const PRESET_NAME = 'notes-assistant';
const EMBEDDED_PRESET = JSON.parse("__PRESET_JSON__");
const EMBEDDED_TEMPLATES = JSON.parse("__TEMPLATE_JSON__");
const EMBEDDED_TEMPLATE_MANIFEST = JSON.parse("__TEMPLATE_MANIFEST_JSON__");

// Shared hook-block parser, loaded from the embedded ESM source (the same file
// note-tools.mjs imports). The memory panel needs the identical parser, so
// we evaluate the shipped source here instead of duplicating the logic.
const HOOK_FRONTMATTER = (() => {
  const source = EMBEDDED_PRESET['hook-frontmatter.mjs'];
  const body = source.replace(/export\s*\{[^}]*\};?\s*$/, '') + '\nreturn { parseHookFrontmatter, stripQuotes };';
  return new Function(body)();
})();

// Host-agnostic memory administration core (the same file the future dsh host
// route consumes). Evaluated from the embedded ESM source; node:fs/path are
// injected from the plugin's CommonJS requires.
const MEMORY_ADMIN = (() => {
  const source = EMBEDDED_PRESET['host-memory-admin.mjs'];
  const body = source
    .replace(/^import\s*\{[^}]*\}\s*from\s*["']node:fs["'];?\s*$/gm, '')
    .replace(/^import\s*\{[^}]*\}\s*from\s*["']node:path["'];?\s*$/gm, '')
    .replace(/^export\s+/gm, '')
    + '\nreturn { pathInside, setHookField, setTopField, setCapturePolicyMode, applyFeedback, archiveMemoryFile, archiveOldEpisodes, parseMemoryFrontmatter, titleOf, daysSinceText, collectMemoryState, readAuditText, FEEDBACK_MESSAGES };';
  return new Function('existsSync', 'mkdirSync', 'writeFileSync', 'readFileSync', 'readdirSync', 'statSync', 'renameSync', 'join', body)(
    existsSync, mkdirSync, writeFileSync, readFileSync, readdirSync, statSync, renameSync, join
  );
})();

const DEFAULT_SETTINGS = {
  port: 3180,
  dshInstallDir: '',
  dshHome: '',
  autoStart: true,
  autoInit: true,
  autoArchiveEpisodes: true,
  showRibbon: true,
  keepAliveOnUnload: false,
  memoryPanelUrl: 'http://127.0.0.1:3080/'
};

// ── small helpers ───────────────────────────────────────────────────────────

function ensureFile(target, content, overwrite = false) {
  if (!overwrite && existsSync(target)) return false;
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content, 'utf8');
  return true;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Probe the local dsh web server with Node's http client. Do NOT use
 * browser `fetch` here: Obsidian's CSP can block renderer-side requests to
 * http://127.0.0.1, which previously made a healthy service look dead.
 */
function probeService(port, timeoutMs = 1500) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    const request = http.get({ host: '127.0.0.1', port, path: '/', timeout: timeoutMs }, (response) => {
      response.resume();
      finish(response.statusCode >= 200 && response.statusCode < 500);
    });
    request.on('error', () => finish(false));
    request.on('timeout', () => {
      request.destroy();
      finish(false);
    });
  });
}

/**
 * The dsh server is a Node program. `process.execPath` inside Obsidian points
 * at the Electron binary (obsidian.exe), never at node, so we spawn `node`
 * from PATH. DSH_NODE_BIN allows an explicit override.
 */
function nodeExecutable() {
  const override = process.env.DSH_NODE_BIN?.trim();
  if (override) return override;
  return process.platform === 'win32' ? 'node.exe' : 'node';
}

// ── memory v2 control surface: deterministic feedback (phase 1a) ──────────

const FEEDBACK_ACTIONS = new Set(['confirm', 'wrong', 'stale', 'forget']);

const FEEDBACK_MESSAGES = MEMORY_ADMIN.FEEDBACK_MESSAGES;

/** Case/separator-robust containment check (win32 lowercases, like the aionui gate). */
const pathInside = MEMORY_ADMIN.pathInside;

/**
 * Set `field: value` inside a block-style hook block (appends the line when
 * absent). Returns the new frontmatter text, or null when there is no
 * block-style hook (flow-style `hook: { ... }` is left untouched).
 */
const setHookField = MEMORY_ADMIN.setHookField;

/** Set a top-level (non-indented) frontmatter field, appending when absent. */
const setTopField = MEMORY_ADMIN.setTopField;

/**
 * Update one capture-policy mode in the vault's .deepseek/capture-policy.md
 * (host side, minimal frontmatter diff; also refreshes the updated date).
 * The settings page dropdowns call this so policy edits never need a text
 * editor; the model is still forbidden from touching the file.
 */
const setCapturePolicyMode = (vault, field, mode) => MEMORY_ADMIN.setCapturePolicyMode(vault, field, mode, typeof EMBEDDED_TEMPLATES['capture-policy.md'] === 'string' ? EMBEDDED_TEMPLATES['capture-policy.md'] : '');

/** Apply one feedback action to a card file (in place, minimal diff). */
const applyFeedback = MEMORY_ADMIN.applyFeedback;

/** Move a memory file into the vault archive (never a hard delete). */
const archiveMemoryFile = MEMORY_ADMIN.archiveMemoryFile;

/**
 * Minimal loopback HTTP server that turns agent replies' note links into
 * Obsidian jumps, and memory feedback links into deterministic frontmatter
 * updates. The dsh agent is told (via env) to render note references as
 * `[title](http://127.0.0.1:<port>/open?path=<vault-relative path>)` and
 * memory feedback as
 * `[✅ 这条对](.../feedback?path=<memory card>&action=confirm)` /
 * `[❌ 这条错](.../feedback?path=<memory card>&action=wrong)`;
 * clicking such a link inside the iframe hits this server, which opens the
 * note / rewrites the card and navigates the iframe back to dsh.
 */
class LinkServer {
  constructor(plugin) {
    this.plugin = plugin;
    this.server = null;
    this.port = 0;
    // CSRF guard for the /feedback mutation endpoint: the token is passed to
    // the dsh agent via DSH_OBSIDIAN_FEEDBACK_TOKEN and must be echoed back
    // in the t= query parameter. Without a token (old paired installs) the
    // endpoint still works for backward compatibility.
    this.token = '';
  }

  start() {
    this.server = createServer((req, res) => {
      const finish = (status, body, html = false) => {
        res.writeHead(status, { 'content-type': html ? 'text/html; charset=utf-8' : 'text/plain; charset=utf-8' });
        res.end(body);
      };
      let url;
      try {
        url = new URL(req.url ?? '/', 'http://127.0.0.1');
      } catch {
        finish(400, 'bad request');
        return;
      }
      if (url.pathname === '/feedback') {
        if (this.token !== '' && url.searchParams.get('t') !== this.token) {
          finish(403, 'bad token');
          return;
        }
        const rawFeedbackPath = url.searchParams.get('path') ?? '';
        const action = url.searchParams.get('action') ?? '';
        const rel = decodeURIComponent(rawFeedbackPath).trim()
          .replace(/\\/g, '/').replace(/^\.\/+/, '').replace(/^\/+/, '');
        const parts = rel.split('/');
        const bad = rel === '' || rel.length > 2000 || !FEEDBACK_ACTIONS.has(action) ||
          parts.some((part) => part === '' || part === '.' || part === '..' || part.includes(':')) ||
          !(rel.startsWith('.deepseek/')) || !rel.toLowerCase().endsWith('.md');
        if (bad) {
          finish(400, 'bad request');
          return;
        }
        try {
          const vaultPath = this.plugin.app.vault.adapter.getBasePath();
          const target = resolve(vaultPath, ...parts);
          if (!pathInside(vaultPath, target)) {
            finish(403, 'path outside vault');
            return;
          }
          if (!existsSync(target)) {
            finish(404, 'file not found');
            return;
          }
          let message;
          if (action === 'forget') {
            archiveMemoryFile(vaultPath, parts);
            message = FEEDBACK_MESSAGES.forget;
          } else {
            const result = applyFeedback(target, action);
            if (!result.ok) {
              finish(400, result.message);
              return;
            }
            message = result.message;
          }
          const display = message.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
          finish(200, `<!doctype html><meta charset="utf-8"><body style="font-family:sans-serif;padding:24px"><p>${display}</p><script>setTimeout(function(){history.back()},600)</script></body>`, true);
        } catch (error) {
          finish(500, String(error));
        }
        return;
      }
      if (url.pathname !== '/open') {
        finish(404, 'not found');
        return;
      }
      // Same CSRF guard as /feedback: without the token, a GET from any
      // webpage could open (or create, via openLinkText on a missing note)
      // arbitrary vault notes while Obsidian is running.
      if (this.token !== '' && url.searchParams.get('t') !== this.token) {
        finish(403, 'bad token');
        return;
      }
      const rawPath = url.searchParams.get('path') ?? url.searchParams.get('note') ?? '';
      const notePath = decodeURIComponent(rawPath).trim();
      if (notePath === '' || notePath.length > 2000) {
        finish(400, 'missing path');
        return;
      }
      try {
        this.plugin.app.workspace.openLinkText(notePath, '', false);
      } catch (error) {
        finish(500, String(error));
        return;
      }
      const display = notePath.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
      finish(200, `<!doctype html><meta charset="utf-8"><body style="font-family:sans-serif;padding:24px"><p>已在 Obsidian 中打开：<code>${display}</code></p><script>setTimeout(function(){history.back()},400)</script></body>`, true);
    });
    try {
      this.token = randomBytes(16).toString('hex');
    } catch {
      this.token = '';
    }
    this.server.listen(0, '127.0.0.1', () => {
      const address = this.server.address();
      this.port = typeof address === 'object' && address !== null ? address.port : 0;
      this.plugin.service?.appendLog(`链接跳转服务已启动：http://127.0.0.1:${this.port}`);
    });
  }

  get baseUrl() {
    return this.port > 0 ? `http://127.0.0.1:${this.port}` : '';
  }

  stop() {
    if (this.server !== null) {
      this.server.close();
      this.server = null;
      this.port = 0;
    }
  }
}

// ── dsh frontend link patch ────────────────────────────────────────────────
// The dsh web frontend renders every http(s) markdown link with target=_blank,
// so our loopback /open and /feedback links open the system browser instead of
// navigating the embedded iframe in place. Patch the installed frontend bundle
// so loopback links stay in-frame (the LinkServer then history.back()s to dsh).
function patchDshFrontendLinks(installDir) {
  if (!installDir) return '跳过 dsh 前端链接补丁：未检测到安装目录';
  const q = String.fromCharCode(34);
  const assetsDir = join(installDir, 'node_modules', '@deepseek-ai', 'dsh-web-frontend', 'dist', 'assets');
  let files = [];
  try {
    files = readdirSync(assetsDir).filter((name) => name.startsWith('index-') && name.endsWith('.js'));
  } catch {
    return '跳过 dsh 前端链接补丁：未找到 dsh-web-frontend/dist/assets';
  }
  if (files.length === 0) return '跳过 dsh 前端链接补丁：assets 目录为空';
  const find = '[' + q + 'http:' + q + ',' + q + 'https:' + q + '].includes(new URL(u).protocol)?{target:' + q + '_blank' + q + ',rel:' + q + 'noopener noreferrer' + q + '}:{}';
  const replace = '(()=>{try{const x=new URL(u);return[' + q + 'http:' + q + ',' + q + 'https:' + q + '].includes(x.protocol)&&![' + q + '127.0.0.1' + q + ',' + q + 'localhost' + q + '].includes(x.hostname)}catch{return false}})()?{target:' + q + '_blank' + q + ',rel:' + q + 'noopener noreferrer' + q + '}:{}';
  let patched = 0;
  for (const name of files) {
    const path = join(assetsDir, name);
    let content;
    try {
      content = readFileSync(path, 'utf8');
    } catch {
      continue;
    }
    if (content.includes(replace)) { patched += 1; continue; }
    if (!content.includes(find)) continue;
    try {
      writeFileSync(path, content.split(find).join(replace), 'utf8');
      patched += 1;
    } catch {
      // best-effort; a read-only install just keeps the old behavior
    }
  }
  return patched > 0 ? 'dsh 前端链接补丁：已处理 ' + patched + ' 个 bundle（loopback 链接改为站内跳转）' : 'dsh 前端链接补丁：无需处理（未命中或已打补丁）';
}

// ── dsh detection ───────────────────────────────────────────────────────────

function validInstallDir(dir) {
  if (!dir) return null;
  const tryRoot = (root) => {
    try {
      const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
      if (manifest.name !== '@deepseek-ai/dsh') return null;
      return { installDir: root, script: join(root, 'lib', 'bin.js') };
    } catch {
      return null;
    }
  };
  // npm-global layout: <dir> itself is @deepseek-ai/dsh
  const direct = tryRoot(dir);
  if (direct) return direct;
  // custom layout: <dir>/dsh is the package (e.g. E:\software\deepseek-harness)
  const nested = tryRoot(join(dir, 'dsh'));
  if (nested) return nested;
  return null;
}

function parseLauncher(cmdPath) {
  try {
    const content = readFileSync(cmdPath, 'utf8');
    const dp0 = dirname(cmdPath);
    const match = /node\s+"([^"]+)"/i.exec(content);
    if (match) {
      let script = match[1].trim();
      if (script.startsWith('%~dp0')) script = join(dp0, script.slice('%~dp0'.length));
      if (script.toLowerCase().endsWith('bin.js') || /lib[\\/]bin\.js/i.test(script)) {
        return { installDir: dirname(dirname(script)), script };
      }
    }
    if (/dsh[\\/]lib[\\/]bin\.js/.test(content)) {
      return { installDir: dp0, script: join(dp0, 'dsh', 'lib', 'bin.js') };
    }
    return { installDir: dp0, script: '' };
  } catch {
    return null;
  }
}

function detectInstallCandidates(settings) {
  const candidates = [];
  if (settings.dshInstallDir) candidates.push(settings.dshInstallDir);
  if (process.env.DSH_HOME) candidates.push(dirname(process.env.DSH_HOME));
  const appData = process.env.APPDATA || join(homedir(), 'AppData', 'Roaming');
  candidates.push(join(appData, 'npm', 'node_modules', '@deepseek-ai', 'dsh'));
  return candidates;
}

function detectFromShell() {
  const result = [];
  let command;
  if (process.platform === 'win32') {
    command = spawnSync('where', ['dsh'], { encoding: 'utf8', timeout: 6000, windowsHide: true });
  } else {
    command = spawnSync('which', ['dsh'], { encoding: 'utf8', timeout: 6000 });
  }
  if (command.status !== 0 || !command.stdout) return result;
  for (const raw of command.stdout.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '') continue;
    const parsed = parseLauncher(line);
    if (parsed) result.push(parsed);
    result.push({ installDir: dirname(line), script: '' });
  }
  return result;
}

function detectDsh(settings) {
  for (const dir of detectInstallCandidates(settings)) {
    const valid = validInstallDir(dir);
    if (valid) return valid;
  }
  for (const parsed of detectFromShell()) {
    const valid = validInstallDir(parsed.installDir);
    if (valid) return valid;
    if (parsed.script) return { installDir: parsed.installDir, script: parsed.script };
  }
  return null;
}

function detectDshHome(settings, detected) {
  if (settings.dshHome) return settings.dshHome;
  if (process.env.DSH_HOME) return process.env.DSH_HOME;
  if (detected?.installDir && existsSync(join(detected.installDir, '.dsh'))) {
    return join(detected.installDir, '.dsh');
  }
  return join(homedir(), '.dsh');
}

// ── dsh service manager ─────────────────────────────────────────────────────

class DshService {
  constructor(plugin) {
    this.plugin = plugin;
    this.child = null;
    this.status = 'unknown';
    this.logLines = [];
    this.listeners = new Set();
    this.cachedLocation = undefined;
  }

  onChange(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    for (const listener of this.listeners) listener(status);
  }

  appendLog(text) {
    for (const line of String(text).split(/\r?\n/)) {
      if (line.trim() === '') continue;
      this.logLines.push(line);
      if (this.logLines.length > 600) this.logLines.shift();
    }
  }

  location(force = false) {
    if (!force && this.cachedLocation !== undefined) return this.cachedLocation;
    const detected = detectDsh(this.plugin.settings);
    this.cachedLocation = detected === null ? null : {
      installDir: detected.installDir,
      script: detected.script,
      home: detectDshHome(this.plugin.settings, detected)
    };
    return this.cachedLocation;
  }

  /**
   * One-shot hint when the port answers but this plugin never spawned the
   * service. Skipped when keepAliveOnUnload is on: a still-running service
   * from the previous Obsidian process is the expected state there.
   */
  warnPortOccupied() {
    if (this.child !== null || this.portOccupiedNotified === true || this.plugin.settings.keepAliveOnUnload) return;
    this.portOccupiedNotified = true;
    this.appendLog(`端口 ${this.plugin.settings.port} 已有其他 HTTP 服务在响应（未由本插件启动）。若侧栏显示的不是 dsh 笔记助手，请在设置中更换端口并重启服务。`);
    new Notice(`dsh 笔记助手：端口 ${this.plugin.settings.port} 已有其他服务在运行。若侧栏内容异常，请在插件设置中更换端口。`);
  }

  async ensureStarted() {
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.warnPortOccupied();
      this.setStatus('running');
      return;
    }
    return this.start();
  }

  async start() {
    if (this.child !== null && this.child.exitCode === null) return;
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.warnPortOccupied();
      this.setStatus('running');
      return;
    }
    const location = this.location();
    if (location === null) {
      this.setStatus('missing-dsh');
      throw new Error('未找到 dsh。请打开插件设置，点击“自动检测”，或先安装 DeepSeek Harness。');
    }
    this.appendLog(patchDshFrontendLinks(location.installDir));
    const patchPath = this.plugin.settings.autoInit
      ? ensureObsidianPatch(location)
      : join(location.home, 'profiles', PRESET_NAME, 'notes-assistant.patch.yml');
    const patchArgs = existsSync(patchPath) ? ['--patch', patchPath] : [];
    const vaultPath = this.plugin.app.vault.adapter.getBasePath();
    const linkBaseUrl = this.plugin.linkServer?.baseUrl ?? '';
    const env = {
      ...process.env,
      DSH_HOME: location.home,
      DSH_OBSIDIAN_VAULT: vaultPath,
      DSH_SESSIONS_ROOT: join(location.home, 'sessions'),
      ...(linkBaseUrl === '' ? {} : { DSH_OBSIDIAN_LINK_URL: linkBaseUrl }),
      ...(this.plugin.linkServer?.token === undefined || this.plugin.linkServer.token === ''
        ? {}
        : { DSH_OBSIDIAN_FEEDBACK_TOKEN: this.plugin.linkServer.token })
    };
    const args = location.script
      ? [location.script, '--profile', PRESET_NAME, ...patchArgs, '--port', String(this.plugin.settings.port)]
      : ['--profile', PRESET_NAME, ...patchArgs, '--port', String(this.plugin.settings.port)];
    const executable = location.script ? nodeExecutable() : 'dsh';
    // Without a resolved script we rely on the dsh launcher; Windows needs a
    // shell to execute .cmd shims.
    const shell = !location.script && process.platform === 'win32';
    this.setStatus('starting');
    this.appendLog(`启动：${executable} ${args.join(' ')}`);
    const child = spawn(executable, args, { env, windowsHide: true, shell, stdio: ['ignore', 'pipe', 'pipe'] });
    this.child = child;
    let spawnError = null;
    child.stdout.on('data', (chunk) => this.appendLog(chunk));
    child.stderr.on('data', (chunk) => this.appendLog(chunk));
    // Without this handler a missing `node` binary throws an uncaught
    // ChildProcess 'error' event and can take the whole plugin down.
    child.on('error', (error) => {
      spawnError = error;
      this.appendLog(`启动失败：${String(error)}`);
      if (this.child === child) this.child = null;
      this.setStatus('error');
    });
    child.on('exit', (code) => {
      this.appendLog(`dsh 已退出，退出码 ${code}`);
      if (this.child === child) this.child = null;
      if (this.status !== 'stopping' && spawnError === null) this.setStatus(code === 0 ? 'stopped' : 'error');
    });
    for (let attempt = 0; attempt < 60; attempt += 1) {
      await sleep(750);
      if (await probeService(this.plugin.settings.port, 1000)) {
        this.setStatus('running');
        return;
      }
      if (this.child === null || this.child.exitCode !== null) break;
    }
    this.setStatus('error');
    throw new Error(`dsh 服务未能在端口 ${this.plugin.settings.port} 上启动。${this.logLines.slice(-3).join(' | ')}`);
  }

  async stop() {
    this.setStatus('stopping');
    const child = this.child;
    this.child = null;
    if (child !== null && child.exitCode === null) {
      const exited = new Promise((resolve) => {
        child.once('exit', resolve);
        setTimeout(resolve, 1500);
      });
      child.kill();
      await exited;
    }
    this.setStatus('stopped');
  }

  async restart() {
    await this.stop();
    await sleep(500);
    return this.start();
  }
}

// ── embedded configuration bootstrap ────────────────────────────────────────

const SKIN_FALLBACK_START = "# --- skin-disable fallback (auto-added: web profile missing) ---";
const SKIN_FALLBACK_END = "# --- end skin-disable fallback ---";

/**
 * Extract the machine-local skin-disable fallback block (if present) so the
 * plugin-owned refresh below never wipes it. The block is appended by
 * syncGlobalPackageLinks when the web profile is missing; without this
 * preservation, the auto-start path overwrites notes-assistant.patch.yml right
 * after the fallback is added and the degraded profile dies on boot again.
 */
function readSkinFallbackBlock(patchPath) {
  try {
    const existing = readFileSync(patchPath, 'utf8');
    const start = existing.indexOf(SKIN_FALLBACK_START);
    const end = existing.indexOf(SKIN_FALLBACK_END, start);
    if (start < 0 || end < 0) return '';
    return existing.slice(start, end + SKIN_FALLBACK_END.length).trim();
  } catch {
    return '';
  }
}

/**
 * Plugin-owned profile overlay: always refresh the auto-workspace host plugin
 * and return the `--patch` path handed to the dsh launcher.
 */
function ensureObsidianPatch(location) {
  const profileRoot = join(location.home, 'profiles', PRESET_NAME);
  ensureFile(join(profileRoot, 'math-memory-workspace.mjs'), EMBEDDED_PRESET['profile-math-memory-workspace.mjs'], true);
  const patchPath = join(profileRoot, 'notes-assistant.patch.yml');
  // Refresh the embedded content AND re-apply the machine-local fallback in
  // one write, so a degraded boot never sees a patch file missing its block.
  const fallback = readSkinFallbackBlock(patchPath);
  const content = EMBEDDED_PRESET['profile-notes-assistant.patch.yml'] + (fallback === '' ? '' : '\n\n' + fallback + '\n');
  try {
    mkdirSync(dirname(patchPath), { recursive: true });
    writeFileSync(patchPath, content, 'utf8');
  } catch {
    // best-effort; boot will surface the real error if this fails
  }
  return patchPath;
}

function bootstrapDshConfig(plugin, force = false) {
  const location = plugin.service.location();
  if (location === null) throw new Error('未检测到 dsh。请先在设置中配置 dsh 安装目录。');
  const home = location.home;
  const presetRoot = join(home, '.agent-presets', PRESET_NAME);
  const profileRoot = join(home, 'profiles', PRESET_NAME);
  const written = [];

  // Code always refreshes; user-editable files are preserved unless forced.
  if (ensureFile(join(presetRoot, 'math-memory.mjs'), EMBEDDED_PRESET['math-memory.mjs'], true)) written.push('preset/math-memory.mjs');
  if (ensureFile(join(presetRoot, 'note-tools.mjs'), EMBEDDED_PRESET['note-tools.mjs'], true)) written.push('preset/note-tools.mjs');
  if (ensureFile(join(presetRoot, 'hook-frontmatter.mjs'), EMBEDDED_PRESET['hook-frontmatter.mjs'], true)) written.push('preset/hook-frontmatter.mjs');
  if (ensureFile(join(presetRoot, 'preset.yml'), EMBEDDED_PRESET['preset.yml'], force)) written.push('preset/preset.yml');
  if (ensureFile(join(presetRoot, 'agent.cordis.yml'), EMBEDDED_PRESET['agent.cordis.yml'], force)) written.push('preset/agent.cordis.yml');
  if (ensureFile(join(profileRoot, 'package.json'), EMBEDDED_PRESET['profile-package.json'], force)) written.push('profile/package.json');
  if (ensureFile(join(profileRoot, 'cordis.yml'), EMBEDDED_PRESET['profile-cordis.yml'], true)) written.push('profile/cordis.yml');
  if (ensureFile(join(profileRoot, 'cordis.patch.yml'), EMBEDDED_PRESET['profile-cordis.patch.yml'], force)) written.push('profile/cordis.patch.yml');
  if (ensureFile(join(profileRoot, 'pnpm-workspace.yaml'), EMBEDDED_PRESET['profile-pnpm-workspace.yaml'], force)) written.push('profile/pnpm-workspace.yaml');
  if (ensureFile(join(profileRoot, 'math-memory-workspace.mjs'), EMBEDDED_PRESET['profile-math-memory-workspace.mjs'], true)) written.push('profile/math-memory-workspace.mjs');
  if (ensureFile(join(profileRoot, 'notes-assistant.patch.yml'), EMBEDDED_PRESET['profile-notes-assistant.patch.yml'], true)) written.push('profile/notes-assistant.patch.yml');
  // Host-plane memory panel + its shared core + the hook parser it imports.
  if (ensureFile(join(profileRoot, 'memory-admin.mjs'), EMBEDDED_PRESET['host-memory-admin.mjs'], true)) written.push('profile/memory-admin.mjs');
  if (ensureFile(join(profileRoot, 'math-memory-panel.mjs'), EMBEDDED_PRESET['host-math-memory-panel.mjs'], true)) written.push('profile/math-memory-panel.mjs');
  if (ensureFile(join(profileRoot, 'hook-frontmatter.mjs'), EMBEDDED_PRESET['hook-frontmatter.mjs'], true)) written.push('profile/hook-frontmatter.mjs');
  return { home, written };
}

/**
 * Durable fix for the global skin-manager patch: $DSH_HOME/cordis.patch.yml
 * inserts the ACTIVE web skin (an @linxin666 package) into EVERY profile, but
 * the obsidian profile carries none of those packages — boot then dies with
 * ERR_MODULE_NOT_FOUND. Instead of maintaining a list of skin ids, mirror
 * every @linxin666 package from the web profile's node_modules into the
 * obsidian profile via junctions (no admin rights needed, one-time per
 * package). Resolution then always succeeds; entries the obsidian profile
 * deliberately disables stay disabled, and any future skin simply resolves.
 */
function syncGlobalPackageLinks(home) {
  const webScope = join(home, 'profiles', 'web', 'node_modules', '@linxin666');
  const obsScope = join(home, 'profiles', PRESET_NAME, 'node_modules', '@linxin666');
  if (!existsSync(webScope)) {
    // Degraded mode: no web profile to mirror from. The global skin insert
    // would break this profile's boot, so append a machine-local disable
    // block to the --patch overlay (re-applied after every plugin-load
    // refresh; marked so it is never duplicated).
    const overlay = join(home, 'profiles', PRESET_NAME, 'notes-assistant.patch.yml');
    try {
      if (existsSync(overlay)) {
        const text = readFileSync(overlay, 'utf8');
        if (!text.includes(SKIN_FALLBACK_START)) {
          const block = [
            '',
            SKIN_FALLBACK_START,
            // The global skin manager writes the ACTIVE skin (one of the
            // ui-skin-* packages) into every profile; without a web profile
            // to mirror from, disable those so boot survives.
            '- id: ui-skin-blue-fantasy',
            '  disabled: true',
            '- id: ui-skin-dragon-heir',
            '  disabled: true',
            '- id: ui-skin-miku',
            '  disabled: true',
            '- id: ui-skin-minecraft',
            '  disabled: true',
            '- id: ui-skin-qq2006',
            '  disabled: true',
            '- id: ui-skin-qq98',
            '  disabled: true',
            '- id: ui-skin-ths',
            '  disabled: true',
            '- id: ui-skin-trading',
            '  disabled: true',
            '- id: ui-skin-whale-song',
            '  disabled: true',
            '- id: ui-skin-xp',
            '  disabled: true',
            SKIN_FALLBACK_END,
            ''
          ].join('\n');
          writeFileSync(overlay, text.replace(/\s+$/, '') + '\n' + block, 'utf8');
        }
      }
    } catch {
      // best-effort; boot will surface the real error if this fails
    }
    return { linked: 0, degraded: true };
  }
  mkdirSync(obsScope, { recursive: true });
  let linked = 0;
  for (const name of readdirSync(webScope)) {
    const target = join(obsScope, name);
    if (existsSync(target)) continue;
    try {
      symlinkSync(join(webScope, name), target, 'junction');
      linked += 1;
    } catch {
      // Skip unlinkable entries; the profile must still boot.
    }
  }
  return { linked, degraded: false };
}

function bootstrapVaultTemplates(plugin, force = false) {
  const vault = plugin.app.vault.adapter.getBasePath();
  const written = [];
  for (const [key, relTarget] of Object.entries(EMBEDDED_TEMPLATE_MANIFEST)) {
    const target = join(vault, ...relTarget.split('/'));
    if (ensureFile(target, EMBEDDED_TEMPLATES[key], force)) written.push(target);
  }
  return { vault, written };
}

/**
 * Host-side memory maintenance: move episode files older than `maxDays` into
 * `episodes/archive/` and update the episode index links. The agent has no
 * delete/move tools, so the Obsidian plugin owns this one lifecycle operation.
 */
const archiveOldEpisodes = MEMORY_ADMIN.archiveOldEpisodes;

// ── sidebar view ────────────────────────────────────────────────────────────

class DshMathView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.offStatus = null;
    this.iframe = null;
  }

  getViewType() {
    return VIEW_TYPE;
  }

  getDisplayText() {
    return 'DSH数学笔记助手';
  }

  getIcon() {
    return 'message-square';
  }

  async onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass('dsh-math-assistant-view');
    this.statusRow = this.contentEl.createDiv({ cls: 'dsh-math-assistant-status' });
    this.body = this.contentEl.createDiv({ cls: 'dsh-math-assistant-body' });
    this.offStatus = this.plugin.service.onChange((status) => this.render(status));
    const status = await this.plugin.service.ensureStarted().then(() => this.plugin.service.status).catch(() => this.plugin.service.status);
    this.render(status);
  }

  render(status) {
    if (this.statusRow === undefined) return;
    if (status === 'running') {
      this.statusRow.empty();
      this.statusRow.style.display = 'none';
      const expectedSrc = `http://127.0.0.1:${this.plugin.settings.port}/`;
      if (this.iframe === null) {
        this.iframe = this.body.createEl('iframe', {
          cls: 'dsh-math-assistant-iframe',
          attr: { src: expectedSrc }
        });
      } else if (this.iframe.getAttribute('src') !== expectedSrc) {
        this.iframe.setAttribute('src', expectedSrc);
      }
      return;
    }
    this.statusRow.style.display = '';
    if (this.iframe !== null) {
      this.iframe.remove();
      this.iframe = null;
    }
    this.statusRow.empty();
    const message = {
      starting: '正在启动 DeepSeek Harness 服务…',
      'missing-dsh': '未找到 dsh（DeepSeek Harness）。请打开插件设置并检测 dsh 安装路径。',
      error: 'dsh 服务启动失败。请打开插件设置查看日志。',
      stopped: 'dsh 服务已停止。',
      stopping: '正在停止服务…',
      unknown: '服务状态未知。'
    }[status] ?? '服务状态未知。';
    this.statusRow.setText(message);
    const actions = this.statusRow.createDiv({ cls: 'dsh-math-assistant-actions' });
    const retry = actions.createEl('button', { text: '重试' });
    retry.addEventListener('click', async () => {
      this.render('starting');
      await this.plugin.service.ensureStarted().catch((error) => new Notice(String(error)));
      this.render(this.plugin.service.status);
    });
    const settings = actions.createEl('button', { text: '打开设置' });
    settings.addEventListener('click', () => this.plugin.openSettings());
  }

  async onClose() {
    if (this.offStatus !== null) this.offStatus();
  }
}

// ── memory panel view (memory v2 control surface, phase 1b) ─────────────────

const VIEW_TYPE_MEMORY = 'dsh-memory-panel';

const VERIFIED_BADGES = {
  'user-confirmed': '✅',
  'cross-referenced': '⚖️',
  'single-source': '❓'
};

/** Parse frontmatter scalars plus an optional block-style hook block. */
const parseMemoryFrontmatter = (text) => MEMORY_ADMIN.parseMemoryFrontmatter(text, HOOK_FRONTMATTER.parseHookFrontmatter);

const titleOf = MEMORY_ADMIN.titleOf;

const daysSinceText = MEMORY_ADMIN.daysSinceText;

/** Collect every memory-layer file under the vault for the panel. */
const collectMemoryState = (vaultPath, filter) => MEMORY_ADMIN.collectMemoryState(vaultPath, filter, HOOK_FRONTMATTER.parseHookFrontmatter);

const readAuditText = MEMORY_ADMIN.readAuditText;

/**
 * In-panel preview for hidden memory files. Obsidian's vault index excludes
 * dot-folders (verified in the 1.13.7 bundle: any path segment starting with
 * "." is hidden), so .deepseek files cannot be opened through openLinkText or
 * any TFile-based API. The panel reads them with node fs and shows them here.
 */
class MemoryPreviewModal extends Modal {
  constructor(app, title, content, fullPath, onSaved = null) {
    super(app);
    this.titleText = title;
    this.contentText = content;
    this.fullPath = fullPath;
    this.onSaved = onSaved;
    this.editing = false;
    this.editorEl = null;
    this.bodyEl = null;
    // mtime snapshot at open time: the conflict guard refuses to clobber
    // external edits made between open and save.
    this.readMtimeMs = 0;
    try {
      this.readMtimeMs = statSync(fullPath).mtimeMs;
    } catch {
      this.readMtimeMs = 0;
    }
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.addClass('dsh-memory-preview');
    contentEl.createEl('h3', { text: this.titleText });
    contentEl.createDiv({ cls: 'dsh-memory-preview-path', text: this.fullPath });
    this.bodyEl = contentEl.createEl('pre', { cls: 'dsh-memory-preview-body', text: this.contentText });
    const actions = contentEl.createDiv({ cls: 'dsh-memory-preview-actions' });
    const edit = actions.createEl('button', { text: '编辑' });
    edit.addEventListener('click', () => this.enterEditMode());
    const copy = actions.createEl('button', { text: '复制内容' });
    copy.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(this.contentText);
        new Notice('已复制到剪贴板');
      } catch (error) {
        new Notice('复制失败：' + String(error));
      }
    });
    const reveal = actions.createEl('button', { text: '在资源管理器中显示' });
    reveal.addEventListener('click', () => {
      try {
        const { shell } = window.require('electron');
        shell.showItemInFolder(this.fullPath);
      } catch (error) {
        new Notice(String(error));
      }
    });
    const openExternal = actions.createEl('button', { text: '用默认应用打开' });
    openExternal.addEventListener('click', async () => {
      try {
        const { shell } = window.require('electron');
        const result = await shell.openPath(this.fullPath);
        if (result !== '') new Notice('打开失败：' + result);
      } catch (error) {
        new Notice(String(error));
      }
    });
    const closeButton = actions.createEl('button', { text: '关闭' });
    closeButton.addEventListener('click', () => this.close());
  }

  enterEditMode() {
    if (this.editing) return;
    this.editing = true;
    this.bodyEl?.remove();
    this.bodyEl = null;
    this.editorEl = this.contentEl.createEl('textarea', { cls: 'dsh-memory-preview-editor' });
    this.editorEl.value = this.contentText;
    const saveRow = this.contentEl.createDiv({ cls: 'dsh-memory-preview-actions' });
    const save = saveRow.createEl('button', { text: '保存', cls: 'mod-cta' });
    save.addEventListener('click', () => this.saveEdit());
    const cancel = saveRow.createEl('button', { text: '取消' });
    cancel.addEventListener('click', () => this.close());
  }

  saveEdit() {
    const value = this.editorEl?.value ?? '';
    let currentMs = 0;
    try {
      currentMs = statSync(this.fullPath).mtimeMs;
    } catch (error) {
      new Notice('无法保存：' + String(error));
      return;
    }
    if (this.readMtimeMs !== 0 && currentMs !== this.readMtimeMs) {
      new Notice('文件已在别处被修改，拒绝覆盖。请关闭后重新打开再编辑。');
      return;
    }
    try {
      writeFileSync(this.fullPath, value, 'utf8');
    } catch (error) {
      new Notice('保存失败：' + String(error));
      return;
    }
    this.close();
    if (typeof this.onSaved === 'function') this.onSaved();
  }

  onClose() {
    this.contentEl.empty();
  }
}

class MemoryView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.filter = '';
  }

  getViewType() {
    return VIEW_TYPE_MEMORY;
  }

  getDisplayText() {
    return 'DSH 记忆面板';
  }

  getIcon() {
    return 'brain';
  }

  vaultPath() {
    return this.app.vault.adapter.getBasePath();
  }

  async onOpen() {
    writeDebugLog('[memory-view] onOpen start');
    const loading = this.contentEl.createDiv({ text: '记忆面板加载中…' });
    try {
      this.contentEl.addClass('dsh-memory-panel');
      const toolbar = this.contentEl.createDiv({ cls: 'dsh-memory-toolbar' });
      const search = toolbar.createEl('input', { type: 'search', placeholder: '搜索记忆卡（标题 / 算子 / 类型 / 主题）' });
      search.value = this.filter;
      search.addEventListener('input', () => {
        this.filter = search.value.trim().toLowerCase();
        this.render();
      });
      const refresh = toolbar.createEl('button', { text: '刷新' });
      refresh.addEventListener('click', () => this.render());
      const archive = toolbar.createEl('button', { text: '归档 >90 天事件' });
      archive.addEventListener('click', () => {
        try {
          const result = archiveOldEpisodes(this.plugin.app.vault.adapter.getBasePath(), 90);
          new Notice(result.moved > 0 ? `记忆维护：已归档 ${result.moved} 个旧事件文件` : '没有需要归档的旧事件');
        } catch (error) {
          new Notice(`记忆维护失败：${String(error)}`);
        }
        this.render();
      });
      this.body = this.contentEl.createDiv({ cls: 'dsh-memory-body' });
      this.render();
    } catch (error) {
      const detail = `记忆面板初始化失败：${String(error)}`;
      this.contentEl.setText(detail);
      this.plugin.service?.appendLog(detail + '\n' + (error?.stack ?? '(no stack)'));
      return;
    }
    loading.remove();
  }

  render() {
    writeDebugLog('[memory-view] render start');
    const body = this.body;
    if (body === undefined) return;
    body.empty();
    try {
      this.renderBody(body);
    } catch (error) {
      body.createDiv({ cls: 'dsh-memory-error', text: `记忆面板渲染失败：${String(error)}` });
    }
  }

  renderBody(body) {
    const state = collectMemoryState(this.vaultPath(), this.filter);
    const summary = [];
    if (state.profile) summary.push('画像 ✅');
    summary.push(`记录 ${state.records.length}`, `模板 ${state.templates.length}`, `备忘录 ${state.memos.length}`, `事件 ${state.episodes.length}`);
    body.createDiv({ cls: 'dsh-memory-summary', text: summary.join(' · ') });
    const policyLink = body.createEl('a', { cls: 'dsh-memory-policy-link', text: `⚙️ 捕获 ${state.capturePolicy.idea}/${state.capturePolicy.fact}/${state.capturePolicy.preference}（点击编辑策略）` });
    policyLink.addEventListener('click', () => this.openNote('.deepseek/capture-policy.md', '捕获策略 capture-policy.md'));

    if (state.records.length > 0) {
      this.section(body, '记忆记录 .deepseek/memory/records/', state.records.length);
      for (const card of state.records) this.cardRow(body, card);
    }
    if (state.templates.length > 0) {
      this.section(body, '问题模板 .deepseek/memory/templates/', state.templates.length);
      for (const card of state.templates) this.cardRow(body, card);
    }
    if (state.memos.length > 0) {
      this.section(body, '备忘录 .deepseek/inbox/', state.memos.length);
      for (const memo of state.memos) this.memoRow(body, memo);
    }
    if (state.episodes.length > 0) {
      this.section(body, '事件时间线 .deepseek/memory/episodes/', state.episodes.length);
      const list = body.createDiv({ cls: 'dsh-memory-rows' });
      for (const episode of state.episodes.slice(0, 30)) {
        const row = list.createDiv({ cls: 'dsh-memory-row' });
        const link = row.createEl('a', { text: episode.name, cls: 'dsh-memory-title' });
        link.addEventListener('click', () => this.openNote(episode.rel));
        row.createDiv({ cls: 'dsh-memory-meta', text: new Date(episode.mtimeMs).toLocaleString('zh-CN', { hour12: false }) });
      }
      if (state.episodes.length > 30) {
        list.createDiv({ cls: 'dsh-memory-meta', text: `… 另有 ${state.episodes.length - 30} 个` });
      }
    }
    if (state.auditText !== '') {
      this.section(body, '记忆体检 .deepseek/cache/memory-audit.json', 1);
      body.createDiv({ cls: 'dsh-memory-audit' }).setText(state.auditText);
    }
    if (state.records.length === 0 && state.templates.length === 0 && state.memos.length === 0 && state.episodes.length === 0) {
      body.createDiv({ cls: 'dsh-memory-meta', text: this.filter === '' ? '记忆库还是空的。与助手对话后，记忆会按 AGENTS.md 逐层写入。' : '没有匹配的记忆。' });
    }
    // Diagnostics footer: always visible so an "empty" panel is self-explanatory.
    body.createDiv({ cls: 'dsh-memory-footer', text: `vault: ${this.vaultPath()} · 过滤: ${this.filter === '' ? '（无）' : this.filter}` });
    writeDebugLog('[memory-view] render done: 记录 ' + state.records.length + ' / 模板 ' + state.templates.length + ' / 备忘录 ' + state.memos.length + ' / 事件 ' + state.episodes.length);
  }

  section(parent, title, count) {
    const head = parent.createDiv({ cls: 'dsh-memory-section' });
    head.createSpan({ cls: 'dsh-memory-section-title', text: title });
    head.createSpan({ cls: 'dsh-memory-meta', text: String(count) });
  }

  // NOTE: must NOT be named "open" — Obsidian's view lifecycle calls
  // view.open(containerEl) when mounting the leaf, so any method with that
  // name overrides the lifecycle hook (this exact bug: the panel stayed
  // blank and the container element was passed to openLinkText).
  // Hidden .deepseek files cannot be opened via Obsidian APIs at all, so
  // clicking a card shows an in-panel preview modal instead.
  openNote(rel, title = null) {
    if (typeof rel !== 'string' || rel === '') return;
    const fullPath = join(this.vaultPath(), ...rel.split('/'));
    try {
      const content = readFileSync(fullPath, 'utf8');
      new MemoryPreviewModal(this.app, title ?? rel, content, fullPath, () => this.render()).open();
    } catch (error) {
      new Notice('无法读取该文件：' + String(error));
    }
  }

  feedback(rel, action) {
    const parts = rel.split('/');
    const filePath = join(this.vaultPath(), ...parts);
    try {
      if (action === 'forget') {
        archiveMemoryFile(this.vaultPath(), parts);
      } else {
        const result = applyFeedback(filePath, action);
        if (!result.ok) {
          new Notice(result.message);
          return;
        }
      }
      new Notice(FEEDBACK_MESSAGES[action]);
    } catch (error) {
      new Notice(`操作失败：${String(error)}`);
      return;
    }
    this.render();
  }

  cardRow(parent, card) {
    const row = parent.createDiv({ cls: 'dsh-memory-row' });
    const title = row.createEl('a', { text: card.title, cls: 'dsh-memory-title' });
    title.addEventListener('click', () => this.openNote(card.rel));
    const parts = [];
    if (card.type !== '') parts.push(card.type);
    if (card.operator !== '') parts.push(card.operator);
    if (card.status !== 'active') parts.push(card.status);
    const badge = VERIFIED_BADGES[card.verified] ?? (card.hook === null ? '' : '❓');
    if (badge !== '') parts.push(badge);
    parts.push(`uses ${card.uses}`);
    if (card.successRate !== null) parts.push(`成功率 ${card.successRate}`);
    const points = Array.isArray(card.history) ? card.history.filter((p) => p !== null && typeof p === 'object') : [];
    if (points.length >= 2) {
      const trend = points.slice(-5).map((p) => `${typeof p.uses === 'number' ? p.uses : 0}${typeof p.successRate === 'number' ? '@' + p.successRate : ''}`).join('→');
      parts.push(`📈 ${trend}`);
    }
    if (card.lastUsed !== '') parts.push(`上次 ${card.lastUsed}`);
    if (card.updated !== '') parts.push(daysSinceText(card.updated));
    row.createDiv({ cls: 'dsh-memory-meta', text: parts.join(' · ') });
    const actions = row.createDiv({ cls: 'dsh-memory-actions' });
    if (card.hook !== null) {
      const confirm = actions.createEl('button', { text: '✅' });
      confirm.title = '确认这条记忆正确（verified → user-confirmed，成功率提至 ≥0.9）';
      confirm.addEventListener('click', () => this.feedback(card.rel, 'confirm'));
      const wrong = actions.createEl('button', { text: '❌' });
      wrong.title = '标记错误（成功率减半，次日体检重新评估）';
      wrong.addEventListener('click', () => this.feedback(card.rel, 'wrong'));
    }
    if (card.status !== 'superseded') {
      const stale = actions.createEl('button', { text: '过期' });
      stale.title = '标记 superseded（保留证据，不删除）';
      stale.addEventListener('click', () => this.feedback(card.rel, 'stale'));
    }
    const forget = actions.createEl('button', { text: '归档' });
    forget.title = '移入 .deepseek/archive/records/（不删除）';
    forget.addEventListener('click', () => this.feedback(card.rel, 'forget'));
  }

  memoRow(parent, memo) {
    const row = parent.createDiv({ cls: 'dsh-memory-row' });
    const title = row.createEl('a', { text: memo.title, cls: 'dsh-memory-title' });
    title.addEventListener('click', () => this.openNote(memo.rel));
    const statusText = { inbox: '待打磨', polishing: '打磨中', done: '已完成' }[memo.status] ?? memo.status;
    const parts = [statusText];
    if (memo.topic !== '') parts.push(memo.topic);
    if (memo.updated !== '') parts.push(daysSinceText(memo.updated));
    row.createDiv({ cls: 'dsh-memory-meta', text: parts.join(' · ') });
  }
}

// ── plugin ──────────────────────────────────────────────────────────────────

class DshObsidianMathPlugin extends Plugin {
  async onload() {
    await this.loadSettings();
    debugVaultPath = this.app.vault.adapter.getBasePath();
    try {
      const debugPath = join(debugVaultPath, '.obsidian', 'plugins', 'dsh-math-assistant', 'debug.log');
      if (existsSync(debugPath) && statSync(debugPath).size > 1024 * 1024) writeFileSync(debugPath, '', 'utf8');
    } catch {
      // rotation is best-effort
    }
    writeDebugLog('=== onload start ===');
    this.service = new DshService(this);

    // Instrumentation: capture the throwing site of every Obsidian toast.
    // Opaque errors like "e.toLowerCase is not a function" are produced by
    // Obsidian internals catching plugin errors and calling new Notice(...);
    // recording the stack at setMessage time reveals the exact caller.
    const pluginRef = this;
    this.originalNoticeSetMessage = null;
    this.noticeWrapper = null;
    if (typeof Notice !== 'undefined' && typeof Notice.prototype?.setMessage === 'function') {
      const originalSetMessage = Notice.prototype.setMessage;
      const wrapper = function (message) {
        try {
          const text = typeof message === 'string' ? message : String(message ?? '');
          if (text.length > 0 && text.length < 400) {
            pluginRef.service?.appendLog('[toast] ' + text + '\n' + (new Error('toast-stack').stack ?? '(no stack)'));
          }
        } catch {
          // never let instrumentation break the toast
        }
        return originalSetMessage.call(this, message);
      };
      Notice.prototype.setMessage = wrapper;
      this.originalNoticeSetMessage = originalSetMessage;
      this.noticeWrapper = wrapper;
    }
    this.linkServer = new LinkServer(this);
    this.linkServer.start();
    this.registerView(VIEW_TYPE, (leaf) => new DshMathView(leaf, this));
    this.registerView(VIEW_TYPE_MEMORY, (leaf) => {
      writeDebugLog('[memory-view] factory invoked');
      return new MemoryView(leaf, this);
    });
    writeDebugLog('memory view registered');
    if (this.settings.showRibbon) {
      this.addRibbonIcon('message-square', '打开 DSH数学笔记助手', () => this.activateView());
    }
    this.addCommand({
      id: 'open-dsh-math-assistant',
      name: '打开 DSH数学笔记助手',
      callback: () => this.activateView()
    });
    this.addCommand({
      id: 'open-dsh-memory-panel',
      name: '打开 DSH 记忆面板',
      callback: () => this.activateMemoryView()
    });
    this.addCommand({
      id: 'open-memory-panel-in-dsh-web',
      name: '在 dsh web 打开记忆面板',
      callback: async () => {
        try {
          await shell.openExternal(this.settings.memoryPanelUrl);
        } catch (error) {
          new Notice(String(error));
        }
      }
    });
    this.addCommand({
      id: 'start-dsh-service',
      name: '启动 DSH 服务',
      callback: async () => {
        try {
          await this.service.start();
          new Notice('DSH 服务已运行');
        } catch (error) {
          new Notice(String(error));
        }
      }
    });
    this.addCommand({
      id: 'stop-dsh-service',
      name: '停止 DSH 服务',
      callback: async () => {
        await this.service.stop();
        new Notice('DSH 服务已停止');
      }
    });
    this.addSettingTab(new DshObsidianSettingTab(this.app, this));
    // Global error traps: memory-panel activation failures so far surfaced as
    // an opaque "e.toLowerCase is not a function" toast from outside our own
    // try/catch. Capture every uncaught error/rejection into the plugin log
    // so the exact throwing site (and its origin URL) becomes visible.
    this.onWindowError = (event) => {
      this.service?.appendLog('[window-error] ' + String(event?.error ?? event?.message) + '\n' + (event?.error?.stack ?? '(no stack)'));
    };
    this.onUnhandledRejection = (event) => {
      const reason = event?.reason;
      this.service?.appendLog('[unhandledrejection] ' + String(reason) + '\n' + (reason?.stack ?? '(no stack)'));
    };
    window.addEventListener('error', this.onWindowError);
    window.addEventListener('unhandledrejection', this.onUnhandledRejection);
    if (this.settings.autoInit) {
      this.app.workspace.onLayoutReady(() => {
        try {
          bootstrapDshConfig(this, false);
          bootstrapVaultTemplates(this, false);
        } catch (error) {
          new Notice(`dsh-math-assistant: ${String(error)}`);
        }
      });
    }
    // Mirror the web profile's @linxin666 packages into the obsidian profile
    // so the global skin insert can always resolve (durable skin fix).
    this.app.workspace.onLayoutReady(() => {
      try {
        const location = this.service.location();
        if (location !== null) {
          const result = syncGlobalPackageLinks(location.home);
          if (result.linked > 0) this.service?.appendLog(`已为 obsidian profile 建立 ${result.linked} 个包链接（皮肤兼容）`);
        }
      } catch (error) {
        this.service?.appendLog(`包链接同步失败：${String(error)}`);
      }
    });
    if (this.settings.autoArchiveEpisodes) {
      this.app.workspace.onLayoutReady(() => {
        try {
          const result = archiveOldEpisodes(this.app.vault.adapter.getBasePath(), 90);
          if (result.moved > 0) new Notice(`记忆维护：已归档 ${result.moved} 个旧事件文件`);
        } catch (error) {
          new Notice(`记忆维护失败：${String(error)}`);
        }
      });
    }
    if (this.settings.autoStart) {
      this.app.workspace.onLayoutReady(() => {
        setTimeout(() => {
          this.service.ensureStarted().catch(() => {});
        }, 1200);
      });
    }
  }

  async activateView() {
    try {
      const { workspace } = this.app;
      let leaf = workspace.getLeavesOfType(VIEW_TYPE)[0] ?? null;
      if (leaf === null) {
        if (typeof workspace.getRightLeaf === 'function') leaf = workspace.getRightLeaf(false);
        if (leaf === null) leaf = workspace.getLeaf('tab');
        await leaf.setViewState({ type: VIEW_TYPE, active: true });
      }
      if (typeof workspace.revealLeaf === 'function') await workspace.revealLeaf(leaf);
      else workspace.setActiveLeaf(leaf);
    } catch (error) {
      new Notice(`无法打开助手面板：${String(error)}`);
    }
  }

  async activateMemoryView() {
    writeDebugLog('[activateMemoryView] enter (typeof VIEW_TYPE_MEMORY=' + typeof VIEW_TYPE_MEMORY + ')');
    try {
      const { workspace } = this.app;
      const viewType = typeof VIEW_TYPE_MEMORY === 'string' ? VIEW_TYPE_MEMORY : 'dsh-memory-panel';
      let leaf = workspace.getLeavesOfType(viewType)[0] ?? null;
      writeDebugLog('[activateMemoryView] existing leaf: ' + (leaf === null ? 'null' : 'found'));
      if (leaf === null) {
        if (typeof workspace.getRightLeaf === 'function') {
          leaf = workspace.getRightLeaf(false);
          writeDebugLog('[activateMemoryView] rightLeaf: ' + (leaf === null ? 'null' : 'leaf'));
        } else {
          writeDebugLog('[activateMemoryView] getRightLeaf missing');
        }
        if (leaf === null) {
          leaf = workspace.getLeaf('tab');
          writeDebugLog('[activateMemoryView] tabLeaf: ' + (leaf === null ? 'null' : 'leaf'));
        }
        await leaf.setViewState({ type: viewType, active: true });
        writeDebugLog('[activateMemoryView] setViewState done');
      }
      if (typeof workspace.revealLeaf === 'function') {
        await workspace.revealLeaf(leaf);
        writeDebugLog('[activateMemoryView] revealLeaf done');
      } else {
        workspace.setActiveLeaf(leaf);
        writeDebugLog('[activateMemoryView] setActiveLeaf done');
      }
    } catch (error) {
      const detail = `无法打开记忆面板：${String(error)}（viewType typeof=${typeof VIEW_TYPE_MEMORY}）`;
      writeDebugLog('[activateMemoryView] FAILED: ' + detail + '\n' + (error?.stack ?? '(no stack)'));
      new Notice(detail);
    }
  }

  openSettings() {
    const setting = this.app.setting;
    if (!setting) return;
    try {
      setting.open();
    } catch {
      // ignored; openTabById below is the important part
    }
    try {
      setting.openTabById(this.manifest.id);
    } catch {
      // older Obsidian: the settings root is already open
    }
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  onunload() {
    this.linkServer?.stop();
    window.removeEventListener('error', this.onWindowError);
    window.removeEventListener('unhandledrejection', this.onUnhandledRejection);
    // Restore the toast instrumentation only if it is still ours (another
    // plugin may have patched setMessage after us).
    if (this.noticeWrapper !== null && typeof Notice !== 'undefined' && Notice.prototype?.setMessage === this.noticeWrapper) {
      Notice.prototype.setMessage = this.originalNoticeSetMessage;
    }
    if (this.service?.child !== null && !this.settings.keepAliveOnUnload) {
      this.service?.stop();
    }
  }
}

module.exports = DshObsidianMathPlugin;

// ── settings tab ────────────────────────────────────────────────────────────

class DshObsidianSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl('h2', { text: 'DSH数学笔记助手' });
    containerEl.createEl('p', { text: `版本 ${this.plugin.manifest?.version ?? ''}` });
    containerEl.createEl('p', { text: '在 Obsidian 右侧栏嵌入 DeepSeek Harness 数学记忆助手。插件会自动启动 dsh 服务，无需额外打开命令行窗口。' });
    containerEl.createEl('p', { cls: 'dsh-math-assistant-security-note', text: '🔒 安全模式：助手只能写当前 vault 内的文件；权限升级审批默认关闭，不会弹出“是否提权”的窗口；工具集中没有删除类工具。' });
    containerEl.createEl('p', { cls: 'dsh-math-assistant-security-note', text: '🧭 适用范围：面向数学类知识（数学、统计学笔记与数学思维方式）设计，其他领域的知识可能需要不同的记忆架构。当前为试做型（0.4.x），记忆架构尚未经过长期使用测试，后续会继续演进。' });

    new Setting(containerEl)
      .setName('端口')
      .setDesc('dsh 网页服务的本地端口。默认 3180，与默认 dsh web 的 3080 互不冲突。')
      .addText((text) => text
        .setPlaceholder('3180')
        .setValue(String(this.plugin.settings.port))
        .onChange(async (value) => {
          const port = Number.parseInt(value, 10);
          if (Number.isInteger(port) && port > 0 && port < 65536) {
            this.plugin.settings.port = port;
            await this.plugin.saveSettings();
          }
        }));

    const location = this.plugin.service.location();
    new Setting(containerEl)
      .setName('dsh 安装目录')
      .setDesc(location ? `已检测到：${location.installDir}` : '尚未检测到。可点击“自动检测”，或手动填写目录后回车。')
      .addText((text) => text
        .setPlaceholder('留空则自动检测')
        .setValue(this.plugin.settings.dshInstallDir)
        .onChange(async (value) => {
          this.plugin.settings.dshInstallDir = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }))
      .addButton((button) => button.setButtonText('自动检测').onClick(async () => {
        const found = this.plugin.service.location(true);
        if (found === null) {
          new Notice('未找到 dsh。请先安装 DeepSeek Harness，或手动填写安装目录。');
        } else {
          this.plugin.settings.dshInstallDir = found.installDir;
          await this.plugin.saveSettings();
          new Notice(`已检测到 dsh：${found.installDir}`);
          this.display();
        }
      }));

    new Setting(containerEl)
      .setName('DSH_HOME')
      .setDesc(location ? `已自动探测：${location.home}（可直接修改）` : 'dsh 主目录（preset、profile、会话日志所在处）。留空则自动探测。')
      .addText((text) => text
        .setPlaceholder('留空则自动探测')
        .setValue(location?.home ?? this.plugin.settings.dshHome)
        .onChange(async (value) => {
          this.plugin.settings.dshHome = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName('启动 Obsidian 时自动启动服务')
      .setDesc('打开 Obsidian 后自动拉起 dsh 服务，无需手动操作。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoStart).onChange(async (value) => {
        this.plugin.settings.autoStart = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('自动初始化 dsh 配置与记忆模板')
      .setDesc('首次运行时自动补齐 preset、profile 与 vault 内的记忆模板（只补缺失文件，不覆盖已有修改）。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoInit).onChange(async (value) => {
        this.plugin.settings.autoInit = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('启动时自动归档旧事件（超过 90 天）')
      .setDesc('把过旧的事件卡移入 episodes/archive/ 并更新索引——由插件执行，agent 本身没有删除/移动工具。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoArchiveEpisodes).onChange(async (value) => {
        this.plugin.settings.autoArchiveEpisodes = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('显示侧边栏按钮')
      .setDesc('在 Obsidian 左侧 ribbon 显示一键打开按钮。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.showRibbon).onChange(async (value) => {
        this.plugin.settings.showRibbon = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('关闭 Obsidian 时保留服务')
      .setDesc('默认关闭：插件退出时会停止它自己启动的 dsh 服务。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.keepAliveOnUnload).onChange(async (value) => {
        this.plugin.settings.keepAliveOnUnload = value;
        await this.plugin.saveSettings();
      }));

    containerEl.createEl('h3', { text: '捕获策略' });
    containerEl.createEl('p', { cls: 'dsh-math-assistant-security-note', text: '控制助手把新信息写入记忆的方式。选择结果直接写入 vault 内的 .deepseek/capture-policy.md（模型不得修改此文件；你的口头指令永远优先于策略）。' });
    containerEl.createEl('p', { text: 'auto = 按三写协议直接写入（回复末尾注明）；ask = 先用提问征得同意再写；off = 不主动捕获（你明确要求除外）。' });
    const captureVault = this.plugin.app.vault.adapter.getBasePath();
    const captureMeta = (() => {
      try {
        const raw = readFileSync(join(captureVault, '.deepseek', 'capture-policy.md'), 'utf8');
        const { meta } = parseMemoryFrontmatter(raw);
        return meta;
      } catch {
        return {};
      }
    })();
    const captureDescriptions = {
      idea: '💡 想法捕获：识别到一般性思路/方法/技巧时，是否写入 inbox 备忘录。',
      fact: '📌 事实捕获：新事实/事件/指令是否写入 records 原子卡（三写第 2 步）。',
      preference: '👤 偏好捕获：稳定偏好/记号/授权是否写入 profile（三写第 3 步）。'
    };
    const addCaptureSetting = (key, fallback) => {
      new Setting(containerEl)
        .setName(captureDescriptions[key])
        .addDropdown((dropdown) => dropdown
          .addOption('ask', 'ask — 先征得同意')
          .addOption('auto', 'auto — 直接写入')
          .addOption('off', 'off — 不主动捕获')
          .setValue(['auto', 'ask', 'off'].includes(captureMeta[key]) ? captureMeta[key] : fallback)
          .onChange(async (value) => {
            try {
              setCapturePolicyMode(this.plugin.app.vault.adapter.getBasePath(), key, value);
              new Notice(`捕获策略已更新：${key} → ${value}`);
            } catch (error) {
              new Notice('更新捕获策略失败：' + String(error));
            }
            this.display();
          }));
    };
    addCaptureSetting('idea', 'ask');
    addCaptureSetting('fact', 'auto');
    addCaptureSetting('preference', 'auto');

    containerEl.createEl('h3', { text: '配置' });
    const configRow = containerEl.createDiv({ cls: 'dsh-math-assistant-config-actions' });
    const initButton = configRow.createEl('button', { text: '初始化 dsh 配置与 vault 模板' });
    initButton.addEventListener('click', async () => {
      try {
        const dsh = bootstrapDshConfig(this.plugin, false);
        const vault = bootstrapVaultTemplates(this.plugin, false);
        new Notice(`dsh 配置已就绪（${dsh.written.length} 个文件）。vault 模板：${vault.written.length} 个。`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const forceButton = configRow.createEl('button', { text: '强制重装 dsh 配置' });
    forceButton.addEventListener('click', async () => {
      try {
        const result = bootstrapDshConfig(this.plugin, true);
        new Notice(`dsh 配置已重装到 ${result.home}`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const archiveButton = configRow.createEl('button', { text: '立即归档旧事件（>90 天）' });
    archiveButton.addEventListener('click', () => {
      try {
        const result = archiveOldEpisodes(this.plugin.app.vault.adapter.getBasePath(), 90);
        new Notice(result.moved > 0 ? `已归档 ${result.moved} 个旧事件文件` : '没有需要归档的旧事件');
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const memoryButton = configRow.createEl('button', { text: '打开记忆面板' });
    memoryButton.addEventListener('click', () => {
      writeDebugLog('[settings] 打开记忆面板 button clicked');
      this.plugin.activateMemoryView();
    });

    containerEl.createEl('h3', { text: '服务' });
    const serviceRow = containerEl.createDiv({ cls: 'dsh-math-assistant-config-actions' });
    const startButton = serviceRow.createEl('button', { text: '启动服务' });
    startButton.addEventListener('click', async () => {
      await this.plugin.service.start().catch((error) => new Notice(String(error)));
      this.display();
    });
    const stopButton = serviceRow.createEl('button', { text: '停止服务' });
    stopButton.addEventListener('click', async () => {
      await this.plugin.service.stop();
      this.display();
    });
    const restartButton = serviceRow.createEl('button', { text: '重启服务' });
    restartButton.addEventListener('click', async () => {
      await this.plugin.service.restart().catch((error) => new Notice(String(error)));
      this.display();
    });
    const statusLabels = {
      running: '运行中',
      starting: '启动中',
      stopped: '已停止',
      stopping: '停止中',
      'missing-dsh': '未找到 dsh',
      error: '错误',
      unknown: '未知'
    };
    serviceRow.createEl('span', { text: ` 状态：${statusLabels[this.plugin.service.status] ?? this.plugin.service.status}` });

    const log = this.plugin.service.logLines.join('\n');
    if (log !== '') {
      containerEl.createEl('h3', { text: `最近服务日志（共 ${this.plugin.service.logLines.length} 行，可滚动）` });
      const copyLog = containerEl.createEl('button', { text: '复制全部日志' });
      copyLog.addEventListener('click', async () => {
        try {
          await navigator.clipboard.writeText(log);
          new Notice('日志已复制到剪贴板');
        } catch {
          new Notice('复制失败，请手动选择日志文本');
        }
      });
      containerEl.createEl('pre', { text: log, cls: 'dsh-math-assistant-log' });
    }
  }
}
